"""Summarize workflow tables without modifying the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re
import sys

EVERY = re.compile(r"[1-9][0-9]*[rsmhd]\Z")
CODE = re.compile(r"[+-]?[0-9]+\Z")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {"routines": ("name", "every", "last_time", "last_code"),
            "schedule": ("name", "at", "claimed")}


def reject_constant(value):
    raise ValueError("invalid JSON constant: " + value)


def read_table(node, table, bad):
    try:
        with (node / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            value = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return []
    except (OSError, UnicodeError, ValueError):
        value = None
    if (not isinstance(value, dict) or value.get("contract") != "wf-table/1"
            or not isinstance(value.get("columns"), list)
            or not all(isinstance(col, str) for col in value["columns"])
            or not isinstance(value.get("rows"), list)):
        bad.append({"table": table, "row": None, "why": "bad_table"})
        return []
    return value["rows"]


def timestamp(text, now):
    stamp = datetime.fromisoformat(text)
    return stamp if stamp.tzinfo is not None else stamp.replace(tzinfo=now.tzinfo)


def routine(row, now):
    every = row["every"]
    if not EVERY.fullmatch(every):
        raise ValueError("invalid interval")
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = "running"
    elif CODE.fullmatch(raw_code):
        code = int(raw_code)
    else:
        raise ValueError("invalid exit code")
    raw_time = row["last_time"]
    last = timestamp(raw_time, now) if raw_time else None
    following = None
    if last is not None and every[-1] != "r":
        # Add in UTC so a representable result does not overflow in the source offset.
        following = last.astimezone(timezone.utc) + timedelta(
            seconds=int(every[:-1]) * SECONDS[every[-1]])
    if code == "running":
        state = "running"
    elif last is None:
        state = "never"
    elif code is not None and code != 0:
        state = "failed"
    elif following is not None and now >= following:
        state = "overdue"
    else:
        state = "ok"
    next_time = (following.isoformat(timespec="seconds").replace("+00:00", "Z")
                 if following is not None else None)
    return {"name": row["name"], "every": every, "last_time": raw_time or None,
            "last_code": code, "state": state, "next": next_time}


def schedule(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    bad = []
    output = {}
    for table in ("routines", "schedule"):
        seen = set()
        items = []
        for index, row in enumerate(read_table(node, table, bad)):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    bad.append({"table": table, "row": index, "why": "dup_name"})
                    continue
                seen.add(name)
            if (not isinstance(row, dict)
                    or not all(isinstance(value, str) for value in row.values())
                    or not all(key in row for key in REQUIRED[table])
                    or not isinstance(name, str) or not name):
                bad.append({"table": table, "row": index, "why": "bad_row"})
                continue
            try:
                items.append(routine(row, now) if table == "routines" else schedule(row, now))
            except (ValueError, OverflowError):
                bad.append({"table": table, "row": index, "why": "bad_row"})
        output[table] = sorted(items, key=lambda item: item["name"])
    routine_states = ("running", "never", "failed", "overdue", "ok")
    schedule_states = ("interrupted", "due", "pending")
    output["counts"] = {
        "routines": {state: sum(item["state"] == state for item in output["routines"])
                     for state in routine_states},
        "schedule": {state: sum(item["state"] == state for item in output["schedule"])
                     for state in schedule_states}}
    output["bad"] = sorted(bad, key=lambda item: (item["table"],
                           -1 if item["row"] is None else item["row"], item["why"]))
    return {"v": 1, **output}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow run summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)
    print(json.dumps(summarize(args.folder, now), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
